#!/usr/bin/env python3
"""Adds the blog post "What Should I Study First for SAT Math?", a card for it at the top of
blog/index.html and an entry in sitemap.xml. Checks fingerprints first; changes nothing unless
everything matches. Undo: python3 studyfirst_oct27.py --undo"""
import sys,os,json,base64,zlib,hashlib,shutil
C=json.loads('{"idx_old": "80fcbe4bf040ffc83a8064054a3f83ee85512040beab261dcd64f0fc51c16eec", "site_old": "5fcd7e9e53b07a2564826848a9d19db00436f43b5e66618c459a4f759ac273f3", "anchor": "<hr class=\\"gold-rule\\">\\n", "card": "<a class=\\"post-card\\" href=\\"/blog/what-to-study-first-for-sat-math.html\\">\\n<p class=\\"meta\\">For Students &middot; October 27, 2026</p>\\n<h2>What Should I Study First for SAT Math? The Order That Saves the Most Time</h2>\\n<p>One full test first, then the basics under your mistakes, then Algebra and Advanced Math. The order a math teacher would use, and why each step comes where it does.</p>\\n</a>\\n", "url": "  <url>\\n    <loc>https://freepracticesat.com/blog/what-to-study-first-for-sat-math.html</loc>\\n    <lastmod>2026-10-27</lastmod>\\n  </url>\\n", "path": "blog/what-to-study-first-for-sat-math.html", "data": "", "fsha": "c0536f471f43518983952445d833c700375b9a2d6aa3d408b3bb90f19dce89c8"}')
BK='.studyfirst_backup_20261027'
sha=lambda b: hashlib.sha256(b).hexdigest()
rd=lambda p: open(p,'rb').read()
IDX='blog/index.html'
if '--undo' in sys.argv:
    if not os.path.isdir(BK): sys.exit('No backup found. Nothing undone.')
    shutil.copyfile(os.path.join(BK,'index.html'),IDX); shutil.copyfile(os.path.join(BK,'sitemap.xml'),'sitemap.xml')
    if os.path.exists(C['path']): os.rename(C['path'],os.path.join(BK,'removed_post.html'))
    print('UNDONE: blog index and sitemap restored, post moved into '+BK+'. Click Republish.'); sys.exit()
idx=rd(IDX); site=rd('sitemap.xml')
if os.path.exists(C['path']) and sha(rd(C['path']))==C['fsha'] and C['path'].encode() in idx:
    print('Already done. Nothing to change.'); sys.exit()
bad=[]
if sha(idx)!=C['idx_old']: bad.append(IDX)
if sha(site)!=C['site_old']: bad.append('sitemap.xml')
if idx.count(C['anchor'].encode())!=1: bad.append(IDX+' (gold rule not found once)')
if os.path.exists(C['path']): bad.append(C['path']+' (already exists)')
if bad:
    print('STOP. Nothing was changed. These files differ from what was checked:'); print('\n'.join(bad)); sys.exit(1)
os.makedirs(BK,exist_ok=True)
shutil.copyfile(IDX,os.path.join(BK,'index.html')); shutil.copyfile('sitemap.xml',os.path.join(BK,'sitemap.xml'))
b=zlib.decompress(base64.b64decode(C['data'])); assert sha(b)==C['fsha']
open(C['path'],'wb').write(b)
a=C['anchor'].encode()
open(IDX,'wb').write(idx.replace(a,a+C['card'].encode()))
open('sitemap.xml','wb').write(site.replace(b'</urlset>',C['url'].encode()+b'</urlset>'))
print('DONE: post added, blog index and sitemap updated. Click Republish.')
